CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('ADMIN','ANALYST') NOT NULL DEFAULT 'ANALYST', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, asset_name VARCHAR(120) NOT NULL UNIQUE, asset_type VARCHAR(40) NOT NULL, ip_address VARCHAR(45) NOT NULL UNIQUE, criticality ENUM('Critical','High','Medium','Low') NOT NULL, operating_system VARCHAR(120), description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_asset_criticality(criticality));
CREATE TABLE IF NOT EXISTS vulnerabilities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cve_id VARCHAR(24) NOT NULL UNIQUE, vulnerability_name VARCHAR(180) NOT NULL, severity ENUM('Critical','High','Medium','Low') NOT NULL, description TEXT NOT NULL, published_date DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_vuln_severity(severity));
CREATE TABLE IF NOT EXISTS asset_vulnerabilities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT UNSIGNED NOT NULL, vulnerability_id BIGINT UNSIGNED NOT NULL, association_status ENUM('Unverified','Suspected','Confirmed','Not Affected') NOT NULL DEFAULT 'Unverified', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_asset_vulnerability(asset_id,vulnerability_id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(vulnerability_id) REFERENCES vulnerabilities(id));
CREATE TABLE IF NOT EXISTS scans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT UNSIGNED NOT NULL, scan_name VARCHAR(160) NOT NULL, scan_profile VARCHAR(80) NOT NULL, scan_type VARCHAR(80) NOT NULL DEFAULT 'Simulated Vulnerability Scan', status ENUM('Pending','Running','Completed','Failed') NOT NULL DEFAULT 'Pending', started_at DATETIME, completed_at DATETIME, created_by BIGINT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS scan_findings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, scan_id BIGINT UNSIGNED NOT NULL, asset_id BIGINT UNSIGNED NOT NULL, vulnerability_id BIGINT UNSIGNED NOT NULL, severity ENUM('Critical','High','Medium','Low') NOT NULL, finding_status ENUM('Open','Resolved','Accepted') NOT NULL DEFAULT 'Open', evidence_summary TEXT NOT NULL, is_simulated BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_scan_vuln(scan_id,vulnerability_id), FOREIGN KEY(scan_id) REFERENCES scans(id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(vulnerability_id) REFERENCES vulnerabilities(id));
CREATE TABLE IF NOT EXISTS correlation_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT UNSIGNED NOT NULL, vulnerability_id BIGINT UNSIGNED NOT NULL, scan_finding_id BIGINT UNSIGNED NOT NULL, threat_report_reference VARCHAR(64) NOT NULL, match_type VARCHAR(40) NOT NULL, match_reason TEXT NOT NULL, risk_score DECIMAL(5,2) NOT NULL, risk_level ENUM('Low','Medium','High','Critical') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_correlation(scan_finding_id,threat_report_reference), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(vulnerability_id) REFERENCES vulnerabilities(id), FOREIGN KEY(scan_finding_id) REFERENCES scan_findings(id));
CREATE TABLE IF NOT EXISTS alerts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, correlation_id BIGINT UNSIGNED NOT NULL UNIQUE, asset_id BIGINT UNSIGNED NOT NULL, vulnerability_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, severity ENUM('Critical','High','Medium','Low') NOT NULL, risk_score DECIMAL(5,2) NOT NULL, status ENUM('Open','Investigating','Resolved','Closed') NOT NULL DEFAULT 'Open', assigned_to BIGINT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(correlation_id) REFERENCES correlation_results(id), FOREIGN KEY(asset_id) REFERENCES assets(id), FOREIGN KEY(vulnerability_id) REFERENCES vulnerabilities(id), FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, alert_id BIGINT UNSIGNED NOT NULL, title VARCHAR(180) NOT NULL, description TEXT, priority ENUM('Critical','High','Medium','Low') NOT NULL, status ENUM('Open','In Progress','Resolved','Closed') NOT NULL DEFAULT 'Open', assigned_to BIGINT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(alert_id) REFERENCES alerts(id), FOREIGN KEY(assigned_to) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS alert_status_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, alert_id BIGINT UNSIGNED NOT NULL, old_status VARCHAR(24) NOT NULL, new_status VARCHAR(24) NOT NULL, changed_by BIGINT UNSIGNED, changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(alert_id) REFERENCES alerts(id), FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE OR REPLACE VIEW vw_alert_overview AS SELECT a.id alert_id,a.title,a.severity,a.risk_score,a.status,a.created_at,asst.asset_name,v.cve_id,u.name assigned_analyst FROM alerts a JOIN assets asst ON a.asset_id=asst.id JOIN vulnerabilities v ON a.vulnerability_id=v.id LEFT JOIN users u ON a.assigned_to=u.id;
CREATE OR REPLACE VIEW vw_ticket_overview AS SELECT t.id ticket_id,t.title,t.priority,t.status,t.created_at,a.id alert_id,asst.asset_name,u.name assigned_analyst FROM tickets t JOIN alerts a ON t.alert_id=a.id JOIN assets asst ON a.asset_id=asst.id LEFT JOIN users u ON t.assigned_to=u.id;
CREATE OR REPLACE VIEW vw_asset_risk_summary AS SELECT a.id,a.asset_name,a.criticality,COALESCE(MAX(c.risk_score),0) max_risk,COUNT(DISTINCT al.id) alert_count FROM assets a LEFT JOIN correlation_results c ON c.asset_id=a.id LEFT JOIN alerts al ON al.asset_id=a.id GROUP BY a.id;
CREATE OR REPLACE VIEW vw_vulnerability_severity_summary AS SELECT severity,COUNT(*) total FROM vulnerabilities GROUP BY severity;
DROP PROCEDURE IF EXISTS sp_vulnerability_severity_report;
CREATE PROCEDURE sp_vulnerability_severity_report() SELECT severity,COUNT(*) total FROM vulnerabilities GROUP BY severity;
DROP PROCEDURE IF EXISTS sp_create_alert_with_ticket;
CREATE PROCEDURE sp_create_alert_with_ticket(IN p_correlation_id BIGINT UNSIGNED, IN p_ticket_title VARCHAR(180), IN p_ticket_description TEXT, IN p_priority VARCHAR(12), IN p_assigned_to BIGINT UNSIGNED, OUT p_alert_id BIGINT UNSIGNED, OUT p_ticket_id BIGINT UNSIGNED)
BEGIN
  DECLARE v_asset_id BIGINT UNSIGNED; DECLARE v_vulnerability_id BIGINT UNSIGNED; DECLARE v_risk DECIMAL(5,2); DECLARE v_severity VARCHAR(12);
  START TRANSACTION;
  SELECT asset_id,vulnerability_id,risk_score,risk_level INTO v_asset_id,v_vulnerability_id,v_risk,v_severity FROM correlation_results WHERE id=p_correlation_id;
  INSERT INTO alerts(correlation_id,asset_id,vulnerability_id,title,description,severity,risk_score) VALUES(p_correlation_id,v_asset_id,v_vulnerability_id,p_ticket_title,p_ticket_description,v_severity,v_risk)
  ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id);
  SET p_alert_id=LAST_INSERT_ID();
  INSERT INTO tickets(alert_id,title,description,priority,assigned_to) VALUES(p_alert_id,p_ticket_title,p_ticket_description,p_priority,p_assigned_to);
  SET p_ticket_id=LAST_INSERT_ID();
  COMMIT;
END;
DROP PROCEDURE IF EXISTS sp_open_alerts_by_asset;
CREATE PROCEDURE sp_open_alerts_by_asset(IN assetId BIGINT UNSIGNED) SELECT * FROM vw_alert_overview WHERE status IN ('Open','Investigating') AND alert_id IN (SELECT id FROM alerts WHERE asset_id=assetId);
DROP TRIGGER IF EXISTS trg_alert_status_audit;
CREATE TRIGGER trg_alert_status_audit AFTER UPDATE ON alerts FOR EACH ROW BEGIN IF OLD.status <> NEW.status THEN INSERT INTO alert_status_audit(alert_id,old_status,new_status,changed_by) VALUES(NEW.id,OLD.status,NEW.status,@changed_by); END IF; END;
